{"code": "const r = await tools.pwsh({description: "Extract key signatures from compile log", command: `cd D:\\lean
$txt = Get-Content 'tmp\\sheaf\\xif\\paper\\S1827Compile.log' -Raw
$lines = $txt -split "\`n"
$keys = @('S1827Comparison :','S1827ConeEssSurj ','S1827ComparisonQuasiEquiv ','S1827MissingCharacterisation','S1827FirstMissing_closure','S1827ComparisonQuasiEquiv_iff_coneEssSurj','S1827FirstMissing_iff_comparisonEquiv','S1827FirstMissing :')
for ($i=0; $i -lt $lines.Count; $i++) {
  foreach ($k in $keys) {
    if ($lines[$i].Contains($k)) { Write-Host ('>>> ' + $lines[$i]); Write-Host ('    ' + $lines[$i+1]); Write-Host ('    ' + $lines[$i+2]); Write-Host ('    ' + $lines[$i+3]) }
  }
}`});
console.log(r.kind==="foreground"? r.stdout.text.slice(0,7000) : JSON.stringify(r));
", "description": "Show key theorem signatures"}

